import 'dart:async';
import 'package:flutter/material.dart';
import 'binance_tr_market.dart';
import 'trading_engine.dart';
void main()=>runApp(const CryptoLoopApp());
class CryptoLoopApp extends StatelessWidget{const CryptoLoopApp({super.key});@override Widget build(BuildContext context)=>MaterialApp(debugShowCheckedModeBanner:false,theme:ThemeData.dark(useMaterial3:true),home:const Dashboard());}
class Dashboard extends StatefulWidget{const Dashboard({super.key});@override State<Dashboard> createState()=>_DashboardState();}
class _DashboardState extends State<Dashboard>{final market=BinanceTrMarket();final engine=TradingEngine();StreamSubscription<double>? sub;double price=0;bool running=false;void toggle(){if(running){sub?.cancel();setState(()=>running=false);return;}sub=market.prices('BTC_TRY').listen((p){engine.onPrice(p);if(mounted)setState(()=>price=p);},onError:(_){if(mounted)setState(()=>running=false);});setState(()=>running=true);}@override void dispose(){sub?.cancel();market.close();super.dispose();}@override Widget build(BuildContext context)=>Scaffold(appBar:AppBar(title:const Text('CryptoLoop TR')),body:Padding(padding:const EdgeInsets.all(16),child:Column(crossAxisAlignment:CrossAxisAlignment.stretch,children:[const Text('PAPER TRADING',style:TextStyle(fontWeight:FontWeight.bold)),const SizedBox(height:16),Text('BTC/TRY  '+(price==0?'--':price.toStringAsFixed(2))+' TL',style:Theme.of(context).textTheme.headlineMedium),const SizedBox(height:12),Text('Durum: '+engine.state.name),Text('Sanal bakiye: '+engine.cashTry.toStringAsFixed(2)+' TL'),Text('Gerceklesen K/Z: '+engine.realizedPnl.toStringAsFixed(2)+' TL'),const SizedBox(height:20),FilledButton(onPressed:toggle,child:Text(running?'BOTU DURDUR':'BOTU BASLAT')),const SizedBox(height:20),const Text('Islemler',style:TextStyle(fontWeight:FontWeight.bold)),Expanded(child:ListView.builder(itemCount:engine.events.length,itemBuilder:(_,i){final e=engine.events[i];return ListTile(title:Text(e.side+' - '+e.price.toStringAsFixed(2)+' TL'),subtitle:Text(e.time.toLocal().toString()),trailing:e.side=='SAT'?Text((e.pnl>=0?'+':'')+e.pnl.toStringAsFixed(2)+' TL'):null);})),])));}
